(() => {
  const $ = id => document.getElementById(id);
  const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const units = [
    {title:'走向门口',description:'她走过走廊，在门前放慢脚步。',action:'她沿着昏暗走廊走向房门，逐渐放慢脚步。',camera:'固定机位',sound:'后期添加',status:'passed'},
    {title:'门口停顿',description:'她听见屋内的声音，手停在门把手前。',action:'她在门外停下，手停在门把手附近。留出两秒停顿，保留迟疑的表情。',camera:'持续推进',sound:'模型生成',status:'issues'},
    {title:'推门进入',description:'她轻轻推门，走进屋内。',action:'她缓慢推开房门，向室内迈出一步。动作连贯自然，保留门外的夜色。',camera:'固定机位',sound:'后期添加',status:'unchecked'}
  ].map(u => ({...u,version:1,direction:'',candidate:null,request:'',duration:'6',ratio:'16:9',model:'视频模型 A',extra:'',history:[],shot:false,confirmed:false}));
  let selected=1,step='instruction',timer=null,toastTimer=null;
  const current=()=>units[selected];
  const issues=u=>[...(u.camera==='持续推进'?[{title:'运镜与停顿不一致',body:'人物已经停下，镜头仍持续推进。建议固定机位，留出停顿。',fix:'镜头改为固定机位，保留人物停顿。'}]:[]),...(u.sound==='模型生成'&&u.model==='视频模型 A'?[{title:'当前模型不支持对白',body:'对白可交给后期。人物动作与画面内容保持不变。',fix:'对白改为后期添加。'}]:[])];
  const full=u=>`${u.action}\n运镜：${u.camera}。\n声音：${u.sound}。\n时长：${u.duration} 秒；画幅：${u.ratio}。${u.extra?'\n补充要求：'+u.extra:''}`;
  function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3200)}
  function modal(title,html){$('modal-title').textContent=title;$('modal-body').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
  $('close-modal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')&&e.clientX<$('modal').getBoundingClientRect().left)$('modal').close()});
  function render(){const u=current();
    $('unit-number').textContent=`单元 0${selected+1} / 03`;$('unit-title').textContent=u.title;$('unit-description').textContent=u.description;$('version').textContent='v'+u.version;
    $('model-label').textContent=u.model;$('duration-label').textContent=u.duration+' 秒';$('ratio-label').textContent=u.ratio;
    $('units').innerHTML=units.map((unit,i)=>`<button class="unit ${selected===i?'selected':''}" data-unit="${i}" ${selected===i?'aria-current="true"':''}><span class="unit-index">0${i+1}</span><span>${unit.title}</span><small>${unit.status==='checking'?'检查中':unit.status==='passed'?'可以试拍':unit.status==='issues'?'待调整':'等待检查'}</small></button>`).join('');
    document.querySelectorAll('[data-unit]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.unit);step='instruction';render()});
    document.querySelectorAll('[data-step]').forEach(b=>{b.toggleAttribute('aria-current',b.dataset.step===step);if(b.dataset.step===step)b.setAttribute('aria-current','step')});
    if(step==='prepare')renderPrepare();else if(step==='results')renderResults();else renderInstruction();
  }
  function renderInstruction(){const u=current(),problems=issues(u),busy=u.status==='checking';
    $('content').innerHTML=`<div class="editor-layout"><section class="editor" aria-label="指令调整"><div class="section-heading"><h2>这次拍什么</h2><span class="muted">当前使用 · v${u.version}</span></div><div class="brief"><div class="brief-title">画面与动作 <button class="text-button" id="edit-fields">直接编辑</button></div><p>${esc(u.action)}</p>${u.extra?`<p class="muted">${esc(u.extra)}</p>`:''}<div class="shot-facts"><div><span>镜头运动</span><strong>${esc(u.camera)}</strong></div><div><span>声音安排</span><strong>${esc(u.sound)}</strong></div></div></div><div class="section-heading section-gap"><h2>你希望怎么调整？</h2><span class="muted" id="draft-label">${u.direction?'草稿 · 尚未采用':'只影响当前单元'}</span></div><div class="composer"><label for="direction" hidden>你希望怎么调整？</label><textarea id="direction" placeholder="例如：镜头保持固定，对白交给后期，其他动作不变。" ${busy?'disabled':''}>${esc(u.direction)}</textarea><div class="composer-bottom"><span>先看修改，再决定是否采用</span><button class="primary" id="generate" ${!u.direction.trim()||busy?'disabled':''}>${u.candidate?'更新修改预览':'预览修改'}</button></div></div><div class="suggestions"><button data-suggestion="镜头改为固定机位，保留人物停顿。">固定机位</button><button data-suggestion="对白改为后期添加。">对白交给后期</button><button data-suggestion="节奏更慢，突出人物的迟疑。">放慢节奏</button></div><div id="proposal"></div><div class="text-link-row"><button class="text-button" id="full">查看完整指令</button><button class="text-button" id="source">查看设计依据</button></div></section><aside class="check-panel" aria-label="检查结论">${checkMarkup(u,problems)}</aside></div>`;
    $('direction').oninput=e=>{u.direction=e.target.value;$('draft-label').textContent=u.direction?'草稿 · 尚未采用':'只影响当前单元';$('generate').disabled=!u.direction.trim()||busy;renderProposal()};
    $('generate').onclick=generate;document.querySelectorAll('[data-suggestion]').forEach(b=>b.onclick=()=>append(b.dataset.suggestion));
    document.querySelectorAll('[data-fix]').forEach(b=>b.onclick=()=>append(problems[Number(b.dataset.fix)].fix));
    if($('fix-all'))$('fix-all').onclick=()=>{u.direction=problems.map(p=>p.fix).join('');render();$('direction').focus()};
    if($('check'))$('check').onclick=check;if($('shoot'))$('shoot').onclick=()=>{u.confirmed=true;step='results';render()};
    if($('mobile-check'))$('mobile-check').onclick=()=>{const expanded=document.querySelector('.check-panel').classList.toggle('expanded');$('mobile-check').textContent=expanded?'收起问题':'查看并处理';$('mobile-check').setAttribute('aria-expanded',String(expanded))};
    if($('check-details'))$('check-details').onclick=()=>modal('检查明细',`<p>检查固定于当前指令 v${u.version}。修改采用后，必须重新检查。</p>${['导演设计','表演动作','场面调度','摄影构图','连续性','提示词'].map((r,i)=>`<div class="history-row"><strong>${r}</strong><small>${problems.length&&(i===3||i===5)?'需要核对':'已通过'}</small></div>`).join('')}`);
    $('edit-fields').onclick=editFields;$('full').onclick=()=>showFull(u);$('source').onclick=()=>modal('本次设计依据','<p>第三场 · 门外</p><div class="brief"><p>她听见屋内的交谈声，伸出的手停在门把手前。片刻之后，她还是推开了门。</p></div><p style="margin-top:18px">设计目标：通过停顿和手部动作表现犹豫。当前单元只负责门前停顿，前后动作分别由其他单元承担。</p>');renderProposal();
  }
  function checkMarkup(u,problems){if(u.status==='checking')return '<div class="check-heading"><h2>检查结论</h2></div><p class="check-summary"><span class="spinner"></span>正在重新检查</p><p class="check-intro">修改已保存，正在核对这份新指令。</p><div class="notice">检查完成前，不会开始试拍。</div>';
    if(u.status==='unchecked')return '<div class="check-heading"><h2>检查结论</h2></div><p class="check-summary">还没有检查</p><p class="check-intro">可以先调整内容，也可以直接检查。</p><button class="primary" id="check">检查这份指令</button>';
    if(u.status==='passed')return `<div class="check-heading"><h2>检查结论</h2><span>v${u.version}</span></div><div class="success-mark">✓</div><h3 class="success-title">可以开始试拍</h3><p class="check-intro" style="margin-top:10px">6 项检查通过。将使用当前指令 v${u.version}。</p><button class="text-button" id="check-details">查看检查明细</button><div class="bottom-action"><p>生成结果仍需人工审片</p><button class="primary" id="shoot">确认结论，前往试拍</button></div>`;
    return `<div class="check-heading"><h2>检查结论</h2><span>v${u.version}</span></div><p class="check-summary">${problems.length} 处需要调整</p><button class="mobile-only text-button" id="mobile-check" aria-expanded="false">查看并处理</button><p class="check-intro">处理后重新检查，就可以试拍。</p>${problems.map((p,i)=>`<div class="issue"><h3>${p.title}</h3><p>${p.body}</p><button class="text-button" data-fix="${i}">加入修改要求</button></div>`).join('')}<p class="passed">✓ 其余 ${6-problems.length} 项已通过</p><button class="text-button" id="check-details">查看检查明细</button><div class="bottom-action"><button class="quiet" id="fix-all">按以上建议调整</button></div>`;
  }
  function append(text){const u=current();if(!u.direction.includes(text))u.direction+=(u.direction?'\n':'')+text;render();$('direction').focus()}
  function generate(){const u=current();if(!u.direction.trim())return;const next={camera:u.camera,sound:u.sound,action:u.action,extra:u.extra};const t=u.direction;
    if(/固定|静止机位/.test(t))next.camera='固定机位';else if(/推进/.test(t))next.camera='持续推进';
    if(/后期/.test(t))next.sound='后期添加';
    const extra=t.split(/[。；\n]/).map(x=>x.trim()).filter(x=>x&&!/固定|静止机位|推进|后期/.test(x)).join('；');if(extra)next.extra=extra;
    u.request=t;u.candidate={...next};renderProposal();$('proposal').scrollIntoView({behavior:'smooth',block:'nearest'});
  }
  function diffs(u){return ['camera','sound','action','extra'].filter(k=>u.candidate[k]!==u[k]).map(k=>({key:k,label:({camera:'运镜',sound:'声音',action:'动作',extra:'要求'})[k],before:u[k]||'无额外要求',after:u.candidate[k]}))}
  function renderProposal(){const u=current();if(!$('proposal'))return;if(!u.candidate){$('proposal').innerHTML='';return}const stale=u.direction!==u.request,changes=diffs(u);
    $('proposal').innerHTML=`<section class="proposal ${stale?'stale':''}" aria-label="修改预览"><div class="proposal-header"><h3>${stale?'修改要求已变化':changes.length?`将调整 ${changes.length} 处`:'当前内容已符合要求'}</h3><span>${stale?'需要更新预览':'尚未采用'}</span></div>${changes.map(c=>`<div class="change"><span>${c.label}</span><div><del>${esc(c.before)}</del><ins>${esc(c.after)}</ins></div></div>`).join('')}<div class="proposal-footer"><p>${stale?'原预览不包含刚才的新要求。':changes.length?'其余内容保留，采用后自动重新检查。':'没有新变化，不会创建空版本。'}</p>${stale?'<button class="primary" id="update">更新修改预览</button>':changes.length?'<button class="primary" id="apply">采用并重新检查</button>':'<button class="quiet" id="dismiss">收起预览</button>'}</div>${changes.length?'<div style="padding:0 20px 16px"><button class="text-button" id="preview-full">查看修改后的完整指令</button></div>':''}</section>`;
    if($('update'))$('update').onclick=generate;if($('dismiss'))$('dismiss').onclick=()=>{u.candidate=null;renderProposal()};if($('preview-full'))$('preview-full').onclick=()=>showFull({...u,...u.candidate},true);if($('apply'))$('apply').onclick=()=>{u.history.unshift({version:u.version,text:full(u)});Object.assign(u,u.candidate);u.version++;u.candidate=null;u.direction='';check()};
    $('generate').textContent=stale?'更新修改预览':u.candidate?'重新预览':'预览修改';
  }
  function check(){const u=current();u.status='checking';u.confirmed=false;render();setTimeout(()=>{u.status=issues(u).length?'issues':'passed';if(current()===u)render();else toast(u.title+' · 检查完成')},1200)}
  function showFull(u,preview=false){modal(preview?'修改后的完整指令':'当前完整指令 · v'+u.version,`<pre>${esc(full(u))}</pre><p>声音“后期添加”只表示制作安排，尚未完成后期制作。</p><details><summary>技术详情</summary><pre>设计版本：design-demo-1\n指令版本：prompt-demo-${u.version}\n示例预览，不对应生产任务。</pre></details>`)}
  function editFields(){const u=current();modal('直接调整当前单元',`<div class="form-grid"><label class="form-field wide">画面与动作<textarea id="field-action">${esc(u.action)}</textarea></label><label class="form-field">镜头运动<select id="field-camera"><option ${u.camera==='固定机位'?'selected':''}>固定机位</option><option ${u.camera==='持续推进'?'selected':''}>持续推进</option></select></label><label class="form-field">声音安排<select id="field-sound"><option ${u.sound==='后期添加'?'selected':''}>后期添加</option><option ${u.sound==='模型生成'?'selected':''}>模型生成</option></select></label></div><div class="form-actions"><button class="primary" id="fields-preview">预览修改</button></div>`);$('fields-preview').onclick=()=>{if(!$('field-action').value.trim()){toast('请保留画面与动作说明');return}u.candidate={action:$('field-action').value,camera:$('field-camera').value,sound:$('field-sound').value,extra:u.extra};u.request=u.direction;$('modal').close();renderProposal();$('proposal').scrollIntoView({block:'nearest'})}}
  function settingsForm(u){return `<div class="form-grid"><label class="form-field wide">视频模型<select id="setting-model"><option ${u.model==='视频模型 A'?'selected':''}>视频模型 A</option><option ${u.model==='视频模型 B · 支持对白'?'selected':''}>视频模型 B · 支持对白</option></select></label><label class="form-field">时长<select id="setting-duration">${['4','6','8'].map(x=>`<option ${u.duration===x?'selected':''} value="${x}">${x} 秒</option>`).join('')}</select></label><label class="form-field">画幅<select id="setting-ratio">${['16:9','9:16','1:1'].map(x=>`<option ${u.ratio===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div class="notice">更换拍摄设置后，需要重新检查指令。已有视频保留。</div><div class="form-actions"><button class="primary" id="save-settings">保存设置，返回检查</button></div>`}
  function bindSettings(){ $('save-settings').onclick=()=>{const u=current(),model=$('setting-model').value,duration=$('setting-duration').value,ratio=$('setting-ratio').value;const changed=model!==u.model||duration!==u.duration||ratio!==u.ratio;if(changed){u.history.unshift({version:u.version,text:full(u)});u.version++;u.candidate=null;Object.assign(u,{model,duration,ratio,status:'unchecked'})}$('modal').close();step='instruction';render();if(changed)toast('拍摄设置已更新，请重新检查')}}
  function renderPrepare(){$('content').innerHTML=`<section class="preparation"><h2>本次拍摄设置</h2><p>当前单元采用文字描述生成。确认模型与输出规格后，进入指令检查。</p>${settingsForm(current())}</section>`;bindSettings()}
  function renderResults(){const u=current();if(u.status==='passed'&&!u.confirmed){$('content').innerHTML='<section class="result-empty"><h2>6 项检查已通过</h2><p>请确认使用这份指令，再开始试拍。</p><button class="primary" id="confirm-review">确认检查结论</button></section>';$('confirm-review').onclick=()=>{u.confirmed=true;renderResults()};return}if(u.status!=='passed'){$('content').innerHTML='<section class="result-empty"><h2>先完成指令检查</h2><p>修改、采用和检查都在上一步完成。<br>检查通过后，再发起试拍。</p><button class="primary" id="back-check">返回调整与检查</button></section>';$('back-check').onclick=()=>{step='instruction';render()};return}
    $('content').innerHTML=u.shot?`<section class="result-card"><div class="result-slate"><span>TAKE 01 · 交互演示</span><h2>此预览不生成真实视频</h2><span>${esc(u.shot.title)} / ${u.shot.duration} SEC / ${u.shot.ratio}</span></div><div class="result-meta"><div><h3>候选 01 · 待审片</h3><p>指令 v${u.shot.version} · 未采用</p></div><button class="quiet" id="review-take">查看审片流程</button></div></section>`:`<section class="result-empty"><span class="status-chip">检查通过</span><h2 style="margin-top:18px">准备拍摄「${esc(u.title)}」</h2><p>当前指令 v${u.version} · ${u.model} · ${u.duration} 秒<br>生成后先审片，再决定是否采用。</p><button class="primary" id="start-shoot">开始试拍（演示）</button></section>`;
    if($('start-shoot'))$('start-shoot').onclick=()=>{u.shot={version:u.version,title:u.title,duration:u.duration,ratio:u.ratio};renderResults();toast('已演示进入候选阶段，没有创建真实拍摄任务')};if($('review-take'))$('review-take').onclick=()=>modal('候选审片','<p>正式产品将在这里播放实际视频，标记可用区间、检查动作覆盖，再由你明确采用。</p><p>当前预览没有真实视频，未执行审片或采用。</p>')}
  document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=b.dataset.step;render()});
  $('settings').onclick=()=>{modal('拍摄设置',settingsForm(current()));bindSettings()};
  $('history').onclick=()=>{const u=current();modal('指令历史',`<p>查看历史不会改变当前拍摄内容。</p><div class="history-row"><div><strong>v${u.version} · 当前使用</strong><small>${u.status==='passed'?'检查通过':u.status==='checking'?'正在检查':'待检查或调整'}</small></div><button id="history-current">查看指令</button></div>${u.history.map((h,i)=>`<div class="history-row"><div><strong>v${h.version}</strong><small>修改前版本 · 已保留</small></div><button data-history="${i}">查看原指令</button></div>`).join('')}`);$('history-current').onclick=()=>showFull(u);document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>modal('历史预览 · v'+u.history[b.dataset.history].version,`<p>当前仍使用 v${u.version}，未切换版本。</p><pre>${esc(u.history[b.dataset.history].text)}</pre>`))};
  document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{if(b.dataset.phase==='shoot'){step='instruction';render()}else modal(b.dataset.phase==='design'?'导演设计':'剪辑验收',b.dataset.phase==='design'?'<p>设计阶段负责场次意图、镜头安排与资产依据。本次重设计聚焦单元试拍，已确认的设计在“查看设计依据”中核对。</p>':'<p>试拍结果经过人工审片、选择可用区间和采用后，进入场次粗剪。修改指令不会替换剪辑中的素材。</p>')});
  $('about').onclick=()=>modal('交互设计预览','<p>本预览使用虚构场次数据，仅演示页面操作，不连接 Jellyfish 项目或生成模型。</p><p>可体验：加入修改要求、预览差异、再次调整、采用复检、切换单元、设置与历史。预览中的文字规则仅用于演示，不代表 AI 生成效果。</p>');
  render();
})();
